# Artist extraction
STOPNAMES = {
    'Sure','thing','Here','are','some','of','my','favorites','favorite','artists','artist','Thanks','Thank','Awesome','Looking','forward','Re','Re:','Got','any','also','as','per','response','Sure thing','Re:'
}

# Normalize punctuation

def normalize_text(s):
    if s is None:
        return ''
    return re.sub(r'\s+', ' ', str(s)).strip()


def extract_artist_names_from_body(body):
    body_n = normalize_text(body)
    if not body_n:
        return []

    # Try to find a segment after favorite(s) artists
    m = re.search(r'(?i)favorite\s+artists?\s*,?\s*', body_n)
    if not m:
        m = re.search(r'(?i)favorites\s+artists?\s*,?\s*', body_n)
    if m:
        seg = body_n[m.end():]
        # cut at end of line/next question-ish
        seg = re.split(r'\?|\n', seg)[0]
        # sometimes ends with extra words
        seg = re.split(r'\bThanks\b|\bthank you\b', seg, flags=re.I)[0]
        # replace ' and ' with commas for splitting
        seg = re.sub(r'\s+and\s+', ',', seg, flags=re.I)
        parts = [p.strip(' .;:!?') for p in seg.split(',')]
        candidates=[]
        for p in parts:
            if not p:
                continue
            # remove leading bullets/quotes
            p = p.strip('"\'‘’')
            if len(p) < 2:
                continue
            # filter stopwords exact match
            if p in STOPNAMES or p.lower() in {x.lower() for x in STOPNAMES}:
                continue
            # Heuristic: keep if starts with capital letter (allow digits for stage names?)
            if re.match(r'^[A-Z0-9][A-Za-z0-9\'\-\. ]+$', p):
                # also avoid common reply prefixes
                if p.lower().startswith('re'):
                    continue
                candidates.append(p)
        # Deduplicate preserving order
        seen=set(); out=[]
        for c in candidates:
            if c.lower() not in seen:
                seen.add(c.lower()); out.append(c)
        return out

    # Fallback: extract capitalized phrases
    # Allow multiword artist names
    phrase_pat = re.compile(r"\b[A-Z][A-Za-z0-9'’.-]*(?:\s+[A-Z][A-Za-z0-9'’.-]*){0,3}\b")
    phrases = phrase_pat.findall(body_n)
    # filter
    out=[]
    seen=set()
    for ph in phrases:
        if ph in STOPNAMES:
            continue
        if ph.lower() in {x.lower() for x in STOPNAMES}:
            continue
        if ph.lower().startswith('re'):
            continue
        # Avoid single-word common words: require at least a space or length>=5
        if ' ' not in ph and len(ph) < 5:
            continue
        if ph.lower() not in seen:
            seen.add(ph.lower()); out.append(ph)
    return out


