        messages.extend(items)
        page_index += 1
        if page_index > 200:
            break
    return messages


coworker_artists = defaultdict(list)  # email -> list
coworker_messages_extracted = []  # for audit

# Extract from coworker emails
for ce in coworker_emails:
    threads = paginate_gmail_inbox_threads(ce)
    print('coworker', ce, 'thread_count', len(threads))
    for t in threads:
        tid = t.get('email_thread_id')
